window.addEventListener("load",function(e){function getScript(source,callback){var script=document.createElement('script');var prior=document.getElementsByTagName('script')[0];script.async=1;script.onload=script.onreadystatechange=function(_,isAbort){if(isAbort||!script.readyState||/loaded|complete/.test(script.readyState)){script.onload=script.onreadystatechange=null;script=undefined;if(!isAbort&&callback)setTimeout(callback,0)}};script.src=source;prior.parentNode.insertBefore(script,prior)}
function addCss(src){var link=document.createElement("link");link.type="text/css";link.rel="stylesheet";link.href=src;document.head.appendChild(link)}
function sliderInit(){addCss('https://cdnjs.cloudflare.com/ajax/libs/Swiper/11.0.5/swiper-bundle.min.css');let swiper1=new Swiper(".hp-sectors-gallery .swiper",{effect:'fade',autoplay:{delay:4000,},on:{slideChange:function(){var currentSlide=this.realIndex+1;document.querySelectorAll('.row.hp-sector').forEach(function(elem){elem.classList.remove('active')});document.querySelector('.row.hp-sector[sector-index="'+currentSlide+'"]').classList.add('active')},}});let swiper2=new Swiper(".hp-sectors-mob .swiper",{effect:'fade',fadeEffect:{crossFade:!0},autoplay:{delay:6000,},pagination:{el:'.swiper-pagination',},})}
let pageLoad=!1;"scroll touchmove".split(" ").forEach(function(e){window.addEventListener(e,function(){if(!pageLoad){getScript('https://cdnjs.cloudflare.com/ajax/libs/Swiper/11.0.5/swiper-bundle.min.js',sliderInit);pageLoad=!0}},!1)})})